use verus::prelude::*;

verus! {

    /// Returns `true` if and only if `n` is a prime number,
    /// according to the mathematical definition:
    ///   n ≥ 2  ∧  ∀ k ∈ ℤ. 2 ≤ k < n ⇒ n mod k ≠ 0.
    pub fn is_prime(n: i8) -> (result: bool)
        ensures
            // Post‐condition exactly captures the definition of primality
            result
            == (n >= 2
                && forall |k: i8|
                     2 <= k && k < n ==>
                     n % k != 0)
    {
        // Any n < 2 is immediately non‐prime.
        if n < 2 {
            return false;
        }

        // We now know n ≥ 2.  Try every candidate divisor k = 2,3,…,n−1.
        let mut k: i8 = 2;
        while k < n
            // Invariant: we still have n ≥ 2
            invariant n >= 2
            // Invariant: 2 ≤ k ≤ n
            invariant 2 <= k && k <= n
            // Invariant: no divisor has been found so far in [2, k)
            invariant forall |j: i8| 2 <= j && j < k ==> n % j != 0
            // We use (n − k) as a well‐founded measure that strictly decreases each loop
            decreases n - k
        {
            // If k divides n, we found a nontrivial divisor → not prime.
            if n % k == 0 {
                return false;
            }
            // Otherwise advance to the next candidate.
            k = k + 1;
        }

        // If we complete the loop with no divisor found,
        // by the loop invariants we know ∀ j ∈ [2,n). n mod j ≠ 0.
        return true;
    }

}